impl Drop for SessionContainer {
    fn drop(&mut self) {
        // Abort both tasks to release Arc references immediately
        if let Ok(mut guard) = self.output_task.try_lock() {
            if let Some(handle) = guard.take() {
                handle.abort();
            }
        }
        if let Ok(mut guard) = self.monomind_task.try_lock() {
            if let Some(handle) = guard.take() {
                handle.abort();
            }
        }
    }
}
